<script>document.addEventListener('DOMContentLoaded',()=>{const business=document.getElementById('transfer-business');const branches=document.getElementById('transfer-branches');if(!business||!branches)return;business.addEventListener('change',()=>{for(const group of branches.querySelectorAll('optgroup')){const visible=group.dataset.business===business.value;group.hidden=!visible;for(const option of group.querySelectorAll('option')){option.selected=false;option.disabled=!visible;}}});business.dispatchEvent(new Event('change'));});</script>
